#!/usr/bin/env bash
#
# cron-job.sh — the one entry point every generated Lupin cron line runs.
#
# Usage:  cron-job.sh <job> [cron|boot]
#
# Cron's environment is bare. This script gives every job the same one: it names the checkout,
# the interpreter and PYTHONPATH, reads the secrets file if there is one, then hands over to
# job_run, which reads the job's command and settings from src/conf/job-registry.json.
# The cron lines are generated by `python -m lupin_mcp.cron_generate`; do not write them by hand.
#
# Secrets (for example JEV_API_TOASTER) live in ~/.lupin/cron.env, mode 600, outside git.
# Name another file with LUPIN_CRON_ENV. A missing file is fine; an unreadable one stops the run.
#
# Exit codes: the job's own, or 64 for no job given, 1 for no interpreter or an unreadable secrets file.
set -uo pipefail

JOB="${1:-}"
TRIGGER="${2:-cron}"
if [ -z "$JOB" ]; then echo "cron-job.sh: usage: cron-job.sh <job> [cron|boot]" >&2; exit 64; fi

export PATH="/usr/local/bin:/usr/bin:/bin:${HOME:-}/.local/bin:${PATH:-}"

SELF="$( readlink -f "${BASH_SOURCE[0]}" )"
ROOT="${LUPIN_ROOT:-$( cd "$( dirname "$SELF" )/../.." && pwd )}"
PYTHON="$ROOT/.venv/bin/python"
if [ ! -x "$PYTHON" ]; then echo "cron-job.sh: no interpreter at $PYTHON" >&2; exit 1; fi

ENV_FILE="${LUPIN_CRON_ENV:-${HOME:-}/.lupin/cron.env}"
if [ -e "$ENV_FILE" ]; then
    if [ ! -r "$ENV_FILE" ]; then echo "cron-job.sh: cannot read $ENV_FILE" >&2; exit 1; fi
    set -a
    # shellcheck disable=SC1090
    . "$ENV_FILE"
    set +a
fi

export LUPIN_ROOT="$ROOT"
export PYTHONPATH="$ROOT/src${PYTHONPATH:+:$PYTHONPATH}"
cd "$ROOT" || exit 1
exec "$PYTHON" -m lupin_mcp.job_run --job "$JOB" --from-registry --trigger "$TRIGGER"
